// Bundled royalty-free music beds, served from public/music like sound effects.
// The audio is generated by scripts/generate-music-beds.sh (pure synthesis, so
// no licensing/attribution) — keep durations here in sync with that script.

export const MUSIC_CATEGORIES = [
  "Upbeat",
  "Chill",
  "Cinematic",
  "Corporate",
] as const

export type MusicCategory = (typeof MUSIC_CATEGORIES)[number]

export const MUSIC_TRACKS = [
  {
    id: "sunrise",
    title: "Sunrise",
    category: "Upbeat",
    fileName: "sunrise.mp3",
    durationMs: 30000,
  },
  {
    id: "neon-drive",
    title: "Neon Drive",
    category: "Upbeat",
    fileName: "neon-drive.mp3",
    durationMs: 20000,
  },
  {
    id: "daydream",
    title: "Daydream",
    category: "Chill",
    fileName: "daydream.mp3",
    durationMs: 30000,
  },
  {
    id: "still-water",
    title: "Still Water",
    category: "Chill",
    fileName: "still-water.mp3",
    durationMs: 45000,
  },
  {
    id: "skyline",
    title: "Skyline",
    category: "Cinematic",
    fileName: "skyline.mp3",
    durationMs: 45000,
  },
  {
    id: "boardroom",
    title: "Boardroom",
    category: "Corporate",
    fileName: "boardroom.mp3",
    durationMs: 24000,
  },
] as const satisfies ReadonlyArray<{
  id: string
  title: string
  category: MusicCategory
  fileName: string
  durationMs: number
}>

export type MusicTrackId = (typeof MUSIC_TRACKS)[number]["id"]

export const MUSIC_TRACK_IDS = MUSIC_TRACKS.map((track) => track.id) as [
  MusicTrackId,
  ...MusicTrackId[],
]

// Length filter buckets (inclusive of the lower bound). "any" skips filtering.
export const MUSIC_LENGTHS = [
  { id: "any", label: "Any length", minMs: 0, maxMs: Infinity },
  { id: "short", label: "Short", minMs: 0, maxMs: 25000 },
  { id: "medium", label: "Medium", minMs: 25000, maxMs: 40000 },
  { id: "long", label: "Long", minMs: 40000, maxMs: Infinity },
] as const

export type MusicLengthId = (typeof MUSIC_LENGTHS)[number]["id"]

export function musicTrackUrl(fileName: string) {
  return `/music/${fileName}`
}

export function getMusicTrack(id: string | undefined) {
  return MUSIC_TRACKS.find((track) => track.id === id) ?? null
}
